
try{(function(){
const btn=document.getElementById('navApps');if(!btn)return;
const mk=(t,c,x)=>{const e=document.createElement(t);if(c)e.className=c;if(x!=null)e.textContent=x;return e};
const d=mk('dialog');d.id='appsDlg';d.setAttribute('aria-label','Nossos apps');document.body.append(d);
const url=()=>window.MH_DOMIN_URL||'labs.html';
const urlM=()=>window.MH_MESA_URL||'mesa.html';
const MLOGO='data:image/webp;base64,';
const DLOGO='data:image/webp;base64,',DMARK='data:image/webp;base64,';
function card(tit,tag,ok,txt,lista,acao){const c=mk('div','ap-c'+(ok?' ap-on':''));const h=mk('h4',0,tit);h.append(mk('span','ap-tag'+(ok?' ok':''),tag));c.append(h,mk('p',0,txt));
 if(lista){const u=mk('ul');lista.forEach(x=>u.append(mk('li',0,x)));c.append(u)}if(acao)c.append(acao);return c}
function abrir(){d.textContent='';
 d.append(mk('h3',0,'Nossos apps'),mk('p','ap-sub','Um só ecossistema da D’Castro Labs: o cliente usa o MiHelp, o profissional gerencia o negócio no Domin e a lanchonete ou o restaurante cuida do cardápio e dos pedidos no MESA. Uma conta só, sem assinar vários apps.'));
 const mh=mk('div','ap-c ap-mihelp');
 const src=(document.querySelector('img.logo.l-dk')||{}).src;
 mh.append(mk('span','ap-tag ok mh-tag','No ar'));
 if(src){const lg=new Image();lg.src=src;lg.alt='MiHelp';lg.className='mh-logo';mh.append(lg)}else mh.append(mk('h4',0,'MiHelp'));
 mh.append(mk('p',0,'A vitrine da cidade: onde as pessoas encontram lojas, profissionais, caronas e serviços, conversam e avaliam.'));
 const ml=mk('ul');['Achar profissionais e lojas perto de você','Guia, caronas e chat da cidade','Avaliações e Voz da Cidade'].forEach(x=>ml.append(mk('li',0,x)));mh.append(ml);
 const here=mk('button','ap-go mh-here','📍 Você está aqui');here.type='button';here.disabled=true;
 mh.append(here,mk('p','mh-lema','Mais do que serviços, é solução.'));d.append(mh);
 const dm=mk('div','ap-c ap-domin');
 const lg=new Image();lg.src=DLOGO;lg.alt='Domin · Gestão empresarial completa, by D’Castro Labs';lg.className='dm-logo';
 dm.append(mk('span','ap-tag ok dm-tag','No ar'),lg,mk('p',0,'A gestão financeira e empresarial da sua empresa registrada, sem sair do ecossistema. Quem tem negócio entra com a mesma conta e cuida de tudo por lá; no MiHelp fica só a vitrine (fotos, contatos, perfil).'));
 const ul=mk('ul');['Caixa, estoque e gastos','Serviços, equipe e agenda','Escalas, ponto e avaliações internas','Vale-funcionário e frente de caixa (PDV)'].forEach(x=>ul.append(mk('li',0,x)));dm.append(ul);
 const go=mk('a','ap-go dm-go');const ic=new Image();ic.src=DMARK;ic.alt='';ic.className='dm-ic';go.append(ic,document.createTextNode('Abrir o Domin'));go.href=url();go.target='_blank';go.rel='noopener noreferrer';
 dm.append(go,mk('p','dm-lema','Mais que apps, um ecossistema.'));d.append(dm);
 const ms=mk('div','ap-c ap-mesa');
 const ml2=new Image();ml2.src=MLOGO;ml2.alt='MESA · Sabor, gestão, conexão';ml2.className='ms-logo';
 ms.append(mk('span','ap-tag ok ms-tag','No ar'),ml2,mk('p',0,'O painel de lanchonetes e restaurantes: monte o cardápio com fotos e preços, acompanhe os pedidos e deixe a loja sempre atualizada aqui no MiHelp.'));
 const msl=mk('ul');['Cardápio digital com fotos, preços e adicionais','Pedidos em andamento, do novo ao entregue','O cardápio vai sozinho para a página da loja no MiHelp','O faturamento segue para o Domin'].forEach(x=>msl.append(mk('li',0,x)));ms.append(msl);
 const mgo=mk('a','ap-go ms-go','Abrir o MESA');mgo.href=urlM();mgo.target='_blank';mgo.rel='noopener noreferrer';
 ms.append(mgo,mk('p','ms-nota','Entra com a mesma conta do MiHelp. Se você ainda não entrou, o MESA pede o telefone e a senha ali mesmo. Entregadores (motoboy) entram em breve no mesmo ecossistema.'),mk('p','ms-lema','Sabor · Gestão · Conexão'));d.append(ms);
 d.append(card('Novos apps','Planejado',false,'O ecossistema da D’Castro Labs vai ganhar outros apps, cada um com a sua função. O Domin continua sendo só a gestão financeira e empresarial.',null,null));
 {const f=document.getElementById('dcLogoFt');if(f){const w=mk('div','dc-by'),i=new Image();i.src=f.src;i.alt=f.alt;w.append(i);d.append(w)}}
 const bar=mk('div','dbt');const cx=mk('button','cx','Fechar');cx.type='button';cx.onclick=()=>d.close();bar.append(cx);d.append(bar);
 if(!d.open)d.showModal()}
btn.addEventListener('click',abrir);
})()}catch(e){console.error('MiHelp (apps):',e)}
